        color = next(iter(colors))
        pix = [(r, c) for r, c in comp if grid[r][c] == color]
        pr0, pc0 = min(r for r, c in pix), min(c for r, c in pix)
        pr1, pc1 = max(r for r, c in pix), max(c for r, c in pix)
